    },
    {
      "document_id": "2482",
      "label": "1",
      "explanation": "The senators highlight their direct role in introducing a resolution to honor Rosa Parks with a statue in the U.S. Capitol. This fits the codebook's clarification of highlighting sponsorship of legislation to secure a symbolic gain or recognition."
    },
    {
      "document_id": "291",
      "label": "1",
      "explanation": "Senator Inhofe explicitly claims credit for provisions in the THUD Appropriations bill, repeatedly using phrases like 'I have fought to include,' 'my language,' and 'my amendment.' This perfectly matches the codebook's definition of highlighting direct involvement in legislative actions that result in tangible gains."
    },
    {
      "document_id": "4550",
      "label": "1",
      "explanation": "Senators Alexander and Corker highlight their co-sponsorship of a bill designed to make the state sales tax deduction permanent, directly emphasizing their role in advocating for a specific financial benefit for their constituents. This matches the codebook's clarification on highlighting sponsorship of legislation."
    },
    {
      "document_id": "229",
      "label": "1",
      "explanation": "Senator Gregg highlights his receipt of an award that recognizes his direct legislative work to strengthen and protect the National Park System. By announcing this recognition and connecting it to his active role in protecting local parks, he is taking credit for his advocacy and legislative actions, which aligns with the codebook's definition of highlighting direct involvement in legislative actions."
    },
    {
      "document_id": "1829",
      "label": "1",
      "explanation": "Senator Johnson explicitly claims credit for securing a grant, with the text stating he 'was instrumental in getting funding for this grant.' This directly matches the codebook's clarification for announcing funding or resources secured for their state and emphasizing their personal role in achieving the outcome."
    },
    {
      "document_id": "834",
      "label": "1",
      "explanation": "Senator Cornyn highlights his receipt of an award recognizing his strong legislative support and key votes for pro-economic growth policies. By emphasizing his legislative record and ongoing push to make tax relief permanent, he claims responsibility for advocating for specific economic benefits, fitting the codebook's criteria for credit-claiming."
    },
    {
      "document_id": "239",
      "label": "1",
      "explanation": "Senator Hutchison highlights her direct involvement in drafting an amendment to restore $3.1 billion in military funding. By stating 'We have crafted an amendment' and sharing the advocacy letter she led, she takes personal responsibility for advocating for a specific funding resource, matching the codebook's definition of credit-claiming."
    },
    {
      "document_id": "541",
      "label": "0",
      "explanation": "Senator Hagel is expressing his opposition to the administration's strategy in Iraq and outlining his policy opinions. He does not claim personal responsibility for securing a specific benefit or highlight direct involvement in achieving a positive outcome. This falls directly under the negative clarification for general statements of opinion and criticism of others without a linked personal achievement."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "4735",
      "label": "1",
      "explanation": "Senator Clinton is explicitly credited by local leaders for her \"help in securing funding\" for the Navy Reserve Center. She also states her ongoing commitment to the project, saying \"I will work very hard to be sure that these funds remain...\" This aligns directly with the codebook's definition of credit-claiming by emphasizing personal advocacy and taking responsibility for delivering a specific resource to her state."
    },
    {
      "document_id": "3879",
      "label": "1",
      "explanation": "Senators Schumer and Clinton announce $30 million for improvements in their state, satisfying the clarification note about \"Announcing funding, grants, or resources they secured for their state.\" Senator Clinton further emphasizes her direct involvement and advocacy by stating she \"will continue to fight for this funding to be included,\" which constitutes credit-claiming."
    },
    {
      "document_id": "1237",
      "label": "1",
      "explanation": "Senator Harkin announces federal grant funding for Story County and the text deliberately points out that he is a \"senior member of the Senate Appropriations Committee.\" By linking his committee position to the announcement of the funds, he implicitly takes personal responsibility for securing the resource, matching the codebook's definition of credit-claiming."
